boards=[("robotics-logos-01-humanoid-robot-companies","Humanoid robot company logos, 01 to 09"),("robotics-logos-02-next-generation-humanoids-and-robot-ai","Next-generation humanoid and robot AI logos, 10 to 18"),("robotics-logos-03-industrial-legged-and-inspection-robots","Industrial, legged, and inspection robot logos, 19 to 27"),("robotics-logos-04-logistics-service-and-field-robots","Logistics, service, and field robot logos, 28 to 36")]
